example.good:
func handleRequest(r Request) (Response, error) {
    data, err := parseRequest(r)
    if err != nil {
        return Response{}, err
    }
    result, err := processData(data)
    if err != nil {
        return Response{}, err
    }
    return formatResponse(result), nil
}

example.bad:
func handleRequest(r Request) (Response, error) {
    // 100 lines of mixed parsing, processing, and formatting
}

