}

func worker(ctx context.Context, jobs <-chan Job) {
    for {
        select {
        case <-ctx.Done():
            return
        case job, ok := <-jobs:
            if !ok {
                return
            }
            process(job)
        }
    }
}

// Sender
func sender(ctx context.Context, out chan<- Result) {
    defer close(out)
    for _, item := range items {
        select {
        case <-ctx.Done():
            return
        case out <- process(item):
        }
    }
}

// Receiver
func receiver(in <-chan Result) {
    for result := range in {
        handle(result)
    }
}
